  "speech_client.py": "import os
import requests

class SpeechClient:
    def __init__(self):
        self.api_key = os.getenv('GOOGLE_CLOUD_SPEECH_API_KEY')
        self.base_url = 'https://speech.googleapis.com/v1p1beta1/'

    def submit_transcription(self, file_path):
        with open(file_path, 'rb') as audio_file:
            files = {'audio': audio_file}
            params = {'config': '{"encoding":"LINEAR16","sampleRateHertz":16000,"languageCode":"en-US"}'}
            headers = {'x-goog-api-key': self.api_key}
            response = requests.post(self.base_url + 'speech:asyncrecognize', files=files, params=params, headers=headers)
            return response.json()

    def poll_transcription(self, job_id):
        headers = {'x-goog-api-key': self.api_key}
        response = requests.get(self.base_url + f'operations/{job_id}', headers=headers)
        return response.json()

    def diarized_transcript(self, file_path):
        with open(file_path, 'rb') as audio_file:
            files = {'audio': audio_file}
            params = {'config': '{"encoding":"LINEAR16","sampleRateHertz":16000,"languageCode":"en-US","enableSpeakerDiarization":true,"diarizationSpeakerCount":2}'}
            headers = {'x-goog-api-key': self.api_key}
            response = requests.post(self.base_url +'speech:asyncrecognize', files=files, params=params, headers=headers)
            return response.json()

    def timestamped_transcript(self, job_id):
        headers = {'x-goog-api-key': self.api_key}
        response = requests.get(self.base_url + f'operations/{job_id}', headers=headers)
        return response.json()",
