  "archive_summary.py": "import os
import requests

def archive_summary(transcript):
    api_key = os.getenv('GOOGLE_CLOUD_LANGUAGE_API_KEY')
    url = 'https://language.googleapis.com/v1/documents:analyzeEntities?key=' + api_key
    payload = {
        'document': {
            'type': 'PLAIN_TEXT',
            'content': transcript
        },
        'encodingType': 'UTF8'
    }
    response = requests.post(url, json=payload)
    return response.json()['entities'][0]['name']",
